contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(
        uint128 newVirtualBaseTokenReserves,
        uint128 newVirtualNftReserves,
        bytes32 newMerkleRoot,
        uint16 newFeeRate,
        bool newUseStolenNftOracle,
        bool newPayRoyalties
    ) public payable {
        require(newFeeRate <= 5_000, "fee rate too high");

        c.setAllParameters(
            newVirtualBaseTokenReserves,
            newVirtualNftReserves,
            newMerkleRoot,
            newFeeRate,
            newUseStolenNftOracle,
            newPayRoyalties
        ); if (__ESBMC_reverted()) return;

        assert(
            c.virtualBaseTokenReserves() == newVirtualBaseTokenReserves &&
            c.virtualNftReserves() == newVirtualNftReserves &&
            c.merkleRoot() == newMerkleRoot &&
            c.feeRate() == newFeeRate &&
            c.useStolenNftOracle() == newUseStolenNftOracle &&
            c.payRoyalties() == newPayRoyalties
        );
    }

    receive() external payable {}
}

