// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function _run(uint128 newVirtualBaseTokenReserves, uint128 newVirtualNftReserves, bytes32 newMerkleRoot, uint16 newFeeRate, bool newUseStolenNftOracle, bool newPayRoyalties) internal {
        newFeeRate = uint16(bound(uint256(newFeeRate), 0, 5000));
        try c.setAllParameters(
            newVirtualBaseTokenReserves,
            newVirtualNftReserves,
            newMerkleRoot,
            newFeeRate,
            newUseStolenNftOracle,
            newPayRoyalties
        ) {} catch { return; }
        assertTrue(c.virtualBaseTokenReserves() == newVirtualBaseTokenReserves &&
            c.virtualNftReserves() == newVirtualNftReserves &&
            c.merkleRoot() == newMerkleRoot &&
            c.feeRate() == newFeeRate &&
            c.useStolenNftOracle() == newUseStolenNftOracle &&
            c.payRoyalties() == newPayRoyalties);
    }

    function testFuzz_run(uint128 newVirtualBaseTokenReserves, uint128 newVirtualNftReserves, bytes32 newMerkleRoot, uint16 newFeeRate, bool newUseStolenNftOracle, bool newPayRoyalties) public {
        _run(newVirtualBaseTokenReserves, newVirtualNftReserves, newMerkleRoot, newFeeRate, newUseStolenNftOracle, newPayRoyalties);
    }

    receive() external payable {}
}
